import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom";

const AdmInfCurso = () => {
  const { id } = useParams();
  const [curso, setCurso] = useState(null);
  const [listaAlunos, setListaAlunos] = useState([]);
  const [alunosSelecionados, setAlunosSelecionados] = useState([]);
  const [professorSelecionado, setProfessorSelecionado] = useState("");
  const [editMode, setEditMode] = useState(false);

  useEffect(() => {
    const fetchCurso = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setCurso(dados);
          setProfessorSelecionado(dados.professor);
          setAlunosSelecionados(dados.alunos || []);
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    const fetchAlunos = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/alunos`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setListaAlunos(dados);
        }
      } catch (error) {
        console.error("Erro na requisição de alunos:", error);
      }
    };

    fetchCurso();
    fetchAlunos();
  }, [id]);

  const handleEditClick = () => setEditMode(true);
  const handleCancelClick = () => {
    setEditMode(false);
    setProfessorSelecionado(curso.professor);
    setAlunosSelecionados(curso.alunos);
  };

  const handleSaveClick = async () => {
    try {
      const resposta = await fetch(`http://localhost:5000/cursos/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          professor: professorSelecionado,
          alunos: alunosSelecionados,
        }),
      });

      if (resposta.ok) {
        setCurso({
          ...curso,
          professor: professorSelecionado,
          alunos: alunosSelecionados,
        });
        setEditMode(false);
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  if (!curso) return <p className="text-center mt-4">Carregando...</p>;

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistprof">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistaluno">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-between align-items-center mt-4">
        <h2>{curso.nome}</h2>
        {!editMode && (
          <button className="btn btn-primary" onClick={handleEditClick}>
            Editar
          </button>
        )}
      </div>

      <div className="d-flex bg-white p-4 rounded shadow mt-3">
        <div className="w-50 pe-4 border-end">
          <h4 className="fw-bold">Informação do Curso</h4>
          <p>
            <strong>{curso.nome}</strong>
          </p>
          <p>{curso.nivel}</p>
          <p>{curso.periodo}</p>
          <p>{curso.area}</p>
        </div>

        <div className="w-50 ps-4">
          <label className="fw-bold">Professor</label>
          {editMode ? (
            <select
              className="form-control mb-2"
              value={professorSelecionado}
              onChange={(e) => setProfessorSelecionado(e.target.value)}
            >
              <option value="">Selecione um professor</option>
              <option value="Paulo Carvalho">Paulo Carvalho</option>
              <option value="Maria Silva">Maria Silva</option>
            </select>
          ) : (
            <p>{curso.professor}</p>
          )}

          <label className="fw-bold mt-3">Alunos</label>
          {editMode ? (
            <select
              className="form-control"
              multiple
              value={alunosSelecionados}
              onChange={(e) =>
                setAlunosSelecionados(
                  [...e.target.selectedOptions].map((o) => o.value)
                )
              }
            >
              {listaAlunos.map((a) => (
                <option key={a.id} value={a.nome}>
                  {a.nome}
                </option>
              ))}
            </select>
          ) : (
            <ul>
              {curso.alunos.map((aluno, index) => (
                <li key={index}>{aluno}</li>
              ))}
            </ul>
          )}

          {editMode && (
            <div className="d-flex justify-content-between mt-3">
              <button className="btn btn-danger" onClick={handleCancelClick}>
                Cancelar
              </button>
              <button className="btn btn-primary" onClick={handleSaveClick}>
                Salvar
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdmInfCurso;
